53	const ITEM_BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	const FIRST_INSURANCE_RATE = 0.1;
62	const CURSE_SURCHARGE_RATE = 0.5;
63	const HIGH_ENCHANTMENT_THRESHOLD = 5;
64	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
65	const PROCESSING_FEE = 5;
66	const LOYALTY_YEARS_THRESHOLD = 2;
67	const LOYALTY_DISCOUNT_RATE = 0.2;
68	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
69	const ALIKE_BLOCK_SIZE = 3;
70	const ALIKE_BLOCK_PREMIUM = 60;
71	
72	const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
73	  const countsByType = new Map<string, number>();
74	  for (const item of items) {
75	    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
76	  }
77	  return countsByType;
78	};
79	
80	const basePremiumForType = (type: string): number => {
81	  const basePremium = ITEM_BASE_PREMIUMS[type];
82	  if (basePremium === undefined) {
83	    throw new Error(`Unknown item type: ${type}`);
84	  }
85	  return basePremium;
86	};
87	
88	const premiumForAlikeGroup = (type: string, count: number): number => {
89	  const basePremium = basePremiumForType(type);
90	  const formsExactlyOneBlock = count === ALIKE_BLOCK_SIZE;
91	  return formsExactlyOneBlock ? ALIKE_BLOCK_PREMIUM : count * basePremium;
92	};
93	
94	const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
95	  let total = 0;
96	  for (const [type, count] of countItemsByType(items)) {
97	    total += premiumForAlikeGroup(type, count);
98	  }
99	  return total;
100	};
101	
102	const itemSurcharge = (
103	  items: QuoteItem[],
104	  applies: (item: QuoteItem) => boolean,
105	  rate: number,
106	): number =>
107	  items.reduce(
108	    (sum, item) =>
109	      applies(item) ? sum + basePremiumForType(item.type) * rate : sum,
110	    0,
111	  );
112	
113	const calculateCurseSurcharge = (items: QuoteItem[]): number =>
114	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);
115	
116	const calculateHighEnchantmentSurcharge = (items: QuoteItem[]): number =>
117	  itemSurcharge(
118	    items,
119	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
120	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
121	  );
122	
123	const calculateQuotePremium = (
124	  items: QuoteItem[],
125	  customer: Customer,
126	  isFollowUpContract: boolean,
127	): number => {
128	  const policyBasePremium = calculatePolicyBasePremium(items);
129	  const curseSurcharge = calculateCurseSurcharge(items);
130	  const highEnchantmentSurcharge = calculateHighEnchantmentSurcharge(items);
131	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
132	  const loyaltyDiscount =
133	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
134	      ? policyBasePremium * LOYALTY_DISCOUNT_RATE
135	      : 0;
136	  const followUpDiscount = isFollowUpContract
137	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
138	    : 0;
139	  return Math.ceil(
140	    policyBasePremium +
141	      curseSurcharge +
142	      highEnchantmentSurcharge +
143	      firstInsuranceSurcharge -
144	      loyaltyDiscount -
145	      followUpDiscount +
146	      PROCESSING_FEE,
147	  );
148	};
149	
150	const ITEM_INSURANCE_VALUES: Record<string, number> = {
151	  sword: 1000,
152	  amulet: 600,
153	  rune: 250,
154	};
155	const DEDUCTIBLE = 100;
156	const PAYOUT_CAP_MULTIPLIER = 2;
157	// Claim-side threshold — a separate business rule from the premium-side
158	// HIGH_ENCHANTMENT_THRESHOLD (5); do not merge them.
159	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
160	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
161	
162	const calculateInsuranceSum = (items: QuoteItem[]): number =>
163	  items.reduce((sum, item) => sum + ITEM_INSURANCE_VALUES[item.type], 0);
164	
165	const initialPayoutCap = (policy: QuoteStep): number =>
166	  calculateInsuranceSum(policy.items) * PAYOUT_CAP_MULTIPLIER;
167	
168	const reimbursementForDamage = (
169	  damage: Damage,
170	  insuredItems: QuoteItem[],
171	): number => {
172	  const damagedItem = insuredItems.find(
173	    (item) => item.type === damage.itemType,
174	  );
175	  if (damagedItem === undefined) {
176	    throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
177	  }
178	  const hasHighEnchantment =
179	    (damagedItem?.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD;
180	  const reimbursedAmount = hasHighEnchantment
181	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
182	    : damage.amount;
183	  return reimbursedAmount - DEDUCTIBLE;
184	};
185	
186	const processClaim = (
187	  claimStep: ClaimStep,
188	  policy: QuoteStep,
189	  remainingCapBefore: number,
190	): ClaimResult => {
191	  const totalReimbursed = claimStep.incident.damages.reduce(
192	    (sum, damage) => sum + reimbursementForDamage(damage, policy.items),
193	    0,
194	  );
195	  const payout = Math.min(Math.floor(totalReimbursed), remainingCapBefore);
196	  return { payout, remainingCap: remainingCapBefore - payout };
197	};
198	
199	export const runScenario = (scenario: Scenario): ScenarioResult => {
200	  const remainingCaps = new Map<number, number>();
201	  const results = scenario.steps.map((step, index): StepResult => {
202	    if (step.op === "claim") {
203	      const policy = scenario.steps[step.policy] as QuoteStep;
204	      const remainingCapBefore =
205	        remainingCaps.get(step.policy) ?? initialPayoutCap(policy);
206	      const result = processClaim(step, policy, remainingCapBefore);
207	      remainingCaps.set(step.policy, result.remainingCap);
208	      return result;
209	    }
210	    const isFollowUpContract = index > 0;
211	    return {
212	      premium: calculateQuotePremium(
213	        step.items,
214	        scenario.customer,
215	        isFollowUpContract,
216	      ),
217	    };
218	  });
219	  return { results };
220	};
221

